    if trans['receiver']['email'] == 'lindseysimpson@gmail.com':
        created_at = datetime.fromisoformat(trans['created_at'])
        days_old = (current_date - created_at).days
        if days_old >= 30:
            old_requests.append(trans)

print(f"Payment requests 30+ days old: {len(old_requests)}")
for trans in old_requests:
    created_at = datetime.fromisoformat(trans['created_at'])
    days_old = (current_date - created_at).days
    print(f"- Transaction {trans['transaction_id']}: {trans['description']} ({days_old} days old) from {trans['sender']['name']}")

