while True:
    response = apis.spotify.show_liked_albums(access_token=token, page_index=page_index)
    if not response:
        break
    for album in response:
        album_details = apis.spotify.show_album(access_token=token, album_id=album['album_id'])
        for song in album_details['songs']:
            all_album_songs.add(song['song_id'])
    page_index += 1
    if len(response) < 50:
        break

print(f"Total songs in liked albums: {len(all_album_songs)}")

