# Check all transactions to see dates and descriptions
for t in transactions:
    print(f"Date: {t['created_at']}, Amount: {t['amount']}, Description: {t['description']}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}")

# Check all transactions and their dates
for t in transactions:
    print(f"Date: {t['created_at']}, Description: {t['description']}, Amount: {t['amount']}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}")

# Let me check all transactions and their dates more carefully
for t in transactions:
    print(f"ID: {t['transaction_id']}, Date: {t['created_at']}, Description: {t['description']}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}")

