action.code:
# Collect all unique song IDs
all_song_ids = set()

# Add from liked songs
for song in liked_songs:
    all_song_ids.add(song['song_id'])

print(f"Songs from liked songs: {len(all_song_ids)}")

# Add from liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        all_song_ids.add(song_id)

print(f"Songs after adding from liked albums: {len(all_song_ids)}")

# Add from playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)

print(f"Total unique songs: {len(all_song_ids)}")

