action.code:
# Sum up all Venmo transactions from yesterday (those are from coworkers paying manager)
total_from_coworkers = 0
coworker_payments = []

for item in recent_items:
    timestamp = item.get('timestamp', '')
    if timestamp.startswith('2023-05-17') and 'venmo' in item.get('type', '').lower():
        amount = item.get('amount', 0)
        if isinstance(amount, str):
            amount = float(amount.replace('$', '').replace(',', ''))
        total_from_coworkers += amount
        coworker_payments.append({
            'description': item.get('description'),
            'amount': amount
        })

print("Coworker Venmo payments from 2023-05-17:")
for payment in coworker_payments:
    print(f"  {payment['description']}: ${payment['amount']}")

print(f"\nTotal from coworkers: ${total_from_coworkers}")
print(f"Your share: $38")
print(f"Total manager paid: ${total_from_coworkers + 38}")

