for tx in transactions:
    if 'azure' in tx.get('description', '').lower() or 'harbor' in tx.get('description', '').lower() or 'bistro' in tx.get('description', '').lower():
        print(f"  {tx}")

# Let me get more transactions by checking multiple pages
all_transactions = []
for page in range(5):
    transactions = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not transactions:
        break
    all_transactions.extend(transactions)

print(f"Total transactions found: {len(all_transactions)}")
print("\nLooking for Azure Harbor Bistro or dinner-related transactions:")
for tx in all_transactions:
    desc = tx.get('description', '').lower()
    if any(word in desc for word in ['azure', 'harbor', 'bistro', 'dinner', 'food', 'restaurant']):
        print(f"  Date: {tx.get('created_at')}, Amount: ${tx.get('amount')}, Desc: {tx.get('description')}, From: {tx.get('sender', {}).get('name')}, To: {tx.get('receiver', {}).get('name')}")

# I don't see Azure Harbor Bistro in the transactions. Let me check if there are more pages
transactions = apis.venmo.show_transactions(access_token=token, page_index=5)
print(f"Page 5: {len(transactions)} transactions")
if transactions:
    for tx in transactions:
        print(f"  {tx.get('description')} - ${tx.get('amount')} - {tx.get('created_at')}")

# Let me get more pages to find the dinner transaction
for page in range(5, 15):
    transactions = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not transactions:
        print(f"No transactions on page {page}")
        break
    all_transactions.extend(transactions)
    print(f"Page {page}: {len(transactions)} transactions")
    # Check if any mention the restaurant
    for tx in transactions:
        desc = tx.get('description', '').lower()
        if any(word in desc for word in ['azure', 'harbor', 'bistro', 'dinner', 'restaurant', 'food', 'manager']):
            print(f"  Found: {tx.get('description')} - ${tx.get('amount')} - {tx.get('created_at')}")

